fn array_sum(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x + y)
     .collect()
}

fn main() {
    let a = vec![1, 2, 3, 4];
    let b = vec![5, 6, 7, 8];
    let c = array_sum(a, b);
    println!("{:?}", c); // prints [6, 8, 10, 12]
}